                if (claim.getPersonId() != person.getId() || status == null || !status.isOpen()
                        || !countsAt(claim, status, person, today)
                        || earlier.stream().noneMatch(p -> !claim.getDueBy().isBefore(p[0]) && !claim.getDueBy().isAfter(p[1]))) {
                    continue;
